#import "ABMCShortcutPanelController.h"

@implementation ABMCShortcutPanelController { NSArray *_items; void (^_selection)(NSDictionary *); UIView *_card; }
- (instancetype)initWithItems:(NSArray *)items selection:(void (^)(NSDictionary *))selection { if((self=[super init])){_items=[items copy];_selection=[selection copy];self.modalPresentationStyle=UIModalPresentationOverFullScreen;self.modalTransitionStyle=UIModalTransitionStyleCrossDissolve;}return self; }
- (void)viewDidLoad {[super viewDidLoad];self.view.backgroundColor=[[UIColor blackColor]colorWithAlphaComponent:.22];UITapGestureRecognizer*t=[[UITapGestureRecognizer alloc]initWithTarget:self action:@selector(backgroundTap:)];[self.view addGestureRecognizer:t];NSUInteger count=MIN(_items.count,(NSUInteger)8),columns=4,rows=(count+columns-1)/columns;CGFloat width=MIN(self.view.bounds.size.width-36,440),height=64+rows*126;_card=[[UIView alloc]initWithFrame:CGRectMake((self.view.bounds.size.width-width)/2,(self.view.bounds.size.height-height)/2,width,height)];_card.autoresizingMask=UIViewAutoresizingFlexibleTopMargin|UIViewAutoresizingFlexibleBottomMargin|UIViewAutoresizingFlexibleLeftMargin|UIViewAutoresizingFlexibleRightMargin;_card.backgroundColor=UIColor.systemBackgroundColor;_card.layer.cornerRadius=28;_card.clipsToBounds=YES;[self.view addSubview:_card];UILabel*title=[[UILabel alloc]initWithFrame:CGRectMake(20,14,width-40,30)];title.text=@"快捷指令";title.textAlignment=NSTextAlignmentCenter;title.font=[UIFont systemFontOfSize:20 weight:UIFontWeightSemibold];[_card addSubview:title];CGFloat step=width/4.0;for(NSUInteger i=0;i<count;i++){NSDictionary*item=_items[i];UIButton*b=[UIButton buttonWithType:UIButtonTypeSystem];b.frame=CGRectMake(i%4*step,52+i/4*126,step,118);b.tag=i;UIImage*image=[UIImage imageWithData:item[@"iconData"]];if(!image)image=[UIImage systemImageNamed:@"square.stack.3d.up.fill"];[b setImage:image forState:UIControlStateNormal];b.imageView.contentMode=UIViewContentModeScaleAspectFit;b.tintColor=UIColor.systemBlueColor;[b addTarget:self action:@selector(select:) forControlEvents:UIControlEventTouchUpInside];UILabel*label=[[UILabel alloc]initWithFrame:CGRectMake(4,76,step-8,38)];label.text=item[@"name"]?:@"快捷指令";label.font=[UIFont systemFontOfSize:15 weight:UIFontWeightMedium];label.textAlignment=NSTextAlignmentCenter;label.numberOfLines=2;label.adjustsFontSizeToFitWidth=YES;label.userInteractionEnabled=NO;[b addSubview:label];[_card addSubview:b];}}
- (void)select:(UIButton *)sender { NSDictionary*item=_items[sender.tag];void(^block)(NSDictionary*)=_selection;[self dismissViewControllerAnimated:YES completion:^{if(block)block(item);}]; }
- (void)backgroundTap:(UITapGestureRecognizer *)tap { if(!CGRectContainsPoint(_card.frame,[tap locationInView:self.view]))[self dismissViewControllerAnimated:YES completion:nil]; }
@end
